import{_ as t,o as e,c as r,a8 as s}from"./chunks/framework.BWjTbCIc.js";const h=JSON.parse('{"title":"香港斯坦福美国学校 · 2026/27学年 · G9-G10 · 考试与面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"stamford-american","school_zh":"香港斯坦福美国学校","school_en":"Stamford American School Hong Kong","grade":"g9-g10","year":"2026-27","year_label":"2026/27学年","type":"mixed","title":"香港斯坦福美国学校 · 2026/27学年 · G9-G10 · 考试与面试","anonymous":true,"source_ids":["INT-STAMFORD-Y9-Y10-2026"],"rounds":["unknown"]},"headers":[],"relativePath":"reports/stamford-american/g9-g10/2026-27-mixed.md","filePath":"reports/stamford-american/g9-g10/2026-27-mixed.md"}'),a={name:"reports/stamford-american/g9-g10/2026-27-mixed.md"};function n(p,o,i,l,g,u){return e(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="香港斯坦福美国学校-·-2026-27学年-·-g9-g10-·-考试与面试" tabindex="-1">香港斯坦福美国学校 · 2026/27学年 · G9-G10 · 考试与面试 <a class="header-anchor" href="#香港斯坦福美国学校-·-2026-27学年-·-g9-g10-·-考试与面试" aria-label="Permalink to &quot;香港斯坦福美国学校 · 2026/27学年 · G9-G10 · 考试与面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/stamford-american">← 返回香港斯坦福美国学校资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-int-stamford-y9-y10-2026" tabindex="-1">资料来源：斯坦福美国学校Y9_Y10线上面试_2026年秋季.pdf <a class="header-anchor" href="#record-int-stamford-y9-y10-2026" aria-label="Permalink to &quot;资料来源：斯坦福美国学校Y9_Y10线上面试_2026年秋季.pdf {#record-int-stamford-y9-y10-2026}&quot;">​</a></h2><p><strong>资料类型：</strong> 面试及题型整理</p><p><strong>入学途径：</strong> 未注明</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>登录与交流</strong></p><p>学生使用学校提供的账号登录系统。一次线上评估中出现短暂加载等待，教师在等待期间已开始英文交流。交流以日常话题为主，整理者认为难度中等、偏基础。</p></blockquote><blockquote><p><strong>英语面谈：</strong> 英语</p><p><strong>自我介绍与学科偏好</strong></p><p>介绍个人情况、年级和兴趣，教师据回答追问。问题包括：</p><ul><li>Which subject do you like the most? Why?</li><li>Which subject do you like the least? Why?</li></ul><p><strong>兴趣与追问</strong></p><ul><li>What are your hobbies?</li><li>What is your favorite book related to your hobby?</li><li>When did you start this hobby?</li><li>How often do you do it?</li></ul></blockquote><blockquote><p><strong>英语机考：</strong> 英语</p><p><strong>听指令点击或拖动</strong></p><p>屏幕呈现教室、乐器室、街道或商店等场景，按录音点击或移动对象。列举的指令包括：</p><ul><li>“Click on the cello.”</li><li>“Click on the instrument.”</li><li>“Drag the backpack to the desk.”</li><li>“Move the violin next to the piano.”</li></ul><p>内容涉及名词、动词及方位介词。整理者认为词汇有一定难度，约B1至B2；这不是校方公布的语言门槛。后续还再次出现同类指令任务。</p><p><strong>快速复述句子</strong></p><p>听一句话后迅速复述。反馈称语速较快、信息量较大，需要尽量准确地保留内容并流畅表达。</p><p><strong>情景回应：餐厅结账</strong></p><p>即将与朋友看电影，需要在餐厅结账，但服务员一直与邻桌交谈。要求说明此时会怎样向服务员表达：“What do you say?”</p><p><strong>情景回应：推迟课堂展示</strong></p><p>原定在生物课进行展示，但同伴当天未到校，希望老师允许推迟至次日。要求说明会怎样提出请求并解释原因。</p><p><strong>听力口头摘要：池塘水样</strong></p><p>录音听1遍，在1分钟内用自己的话总结。主题是一名学生学习水质后，对自幼常去、位于家附近的池塘产生兴趣，取少量水样带回实验室；周一用滴管将一滴水放在载玻片上，以显微镜观察其中不同的微小物质，感到十分着迷。内容为题意整理，非逐字题干。</p><p><strong>视频或录音口头摘要：星座</strong></p><p>材料播放2遍，在1分钟内用自己的话总结。内容涉及星座图案可呈动物、战士或人造物体；人类在数千年观察中命名这些图案，天文学家利用星座定位行星、彗星等。材料还提到88个有明确边界的星座及1922年国际天文学联合会的认可。</p><p><strong>视频或录音口头摘要：城市化</strong></p><p>同类任务涉及人口从乡村迁往城市：人们为工作及乡村缺少的机会迁居，乡村人口减少；材料称当时约一半人口居住城市，并预测2050年比例约70%。需在限定时间内概括，材料中的比例按题意保留。</p><p><strong>听力书面摘要：柯伊伯带</strong></p><p>听2段录音，在10分钟内完成书面摘要，随后简短回答问题。材料涉及1992年发现柯伊伯带、位于海王星外侧、天体源自约46亿年前的太阳系形成期；由于距离远且体积小，观测困难。材料以冥王星说明这些天体及其历史分类。附加问题为：“What is the most famous Kuiper Belt Object?”</p><p><strong>听力书面摘要：眼睛颜色遗传</strong></p><p>同类任务使用简化遗传模型：孩子分别从父母获得一个基因，棕色B为显性、蓝色b为隐性；两份棕色或一棕一蓝表现为棕色，两份蓝色表现为蓝色。模型中父母均为Bb，孩子棕眼概率75%、蓝眼概率25%。附加问题：“Why is the child more likely to have brown eyes?” 此处为考题模型的表述。</p><p><strong>朗读与短答：鳄鱼和短吻鳄</strong></p><p>朗读短文并回答一个问题。短文比较栖息地与颌部：鳄鱼可生活在淡水或咸水，短吻鳄主要生活在淡水；鳄鱼颌部较长、较窄，短吻鳄较圆。问题为：“Where do alligators usually live?”</p><p><strong>朗读与短答：学校迷宫筹款</strong></p><p>学生在学校体育馆搭建大型迷宫，让其他学生参与，以筹集体育活动经费，最终筹足所需款项。问题为：“Where was the maze?”</p><p><strong>词语放入句子</strong></p><p>系统给出词语及句子框架，要求将词放入正确位置，使语义和语法完整。</p><p><strong>看图选词填空</strong></p><p>结合图片和句子，从所给词汇中选词填入空格。具体实测图片未明确，另列的教学示例不作为实测题目。</p><p><strong>阅读后写摘要：硬币制造成本</strong></p><p>先阅读3分钟，随后文章自动收起，不能再查看；用10分钟回答“What did you learn from the passage?”。材料讨论加拿大和美国的1美分硬币：加拿大于2012年决定停产，制造100枚成本为1.60元，面值仅1元；美国制造100枚成本为2.50元，材料推测其未来也可能停产。以上按历史题材表述保留。</p><p><strong>阅读后写摘要：电影片场之旅</strong></p><p>同类题材讲述一名男孩赢得电台游戏，获赠与家人参观好莱坞新电影拍摄的旅行。他们观看一天拍摄；最喜爱的主演欢迎他，他还试穿戏服，全家与演员合照，并计划当晚到当地高档餐厅用餐。他认为这是最美好的一天。</p><p><strong>专业词汇朗读</strong></p><p>教师共享屏幕，学生逐词朗读，关注读音、重音及流畅度；不要求释义、拼写或造句。两组词汇如下：</p><ul><li>A组：boutique、meddle、supplement、whimsical、grotesque、nonchalant、contemptuous、antique、miniature、simultaneous。</li><li>B组：exuberant、permissive、inducement、exhibition、articulate、subtle、granular、succumb、poignant、rambunctious。</li></ul></blockquote>',11)])])}const d=t(a,[["render",n]]);export{h as __pageData,d as default};
